inline uint64_t odyssey_responsibility(uint64_t s,uint64_t ordinal) {
 if(s==1)return F04_CAPTAIN;
 if(s==2)return F04_FIRST;
 if(s==3 && ordinal==1)return F04_SECOND;
 if(s==65)return ordinal==1?F04_DOCTOR:0;
 if(s==11 || s==23 || s==35 || s==47 || s==57)
  return ordinal==1?F04_HEAD:ordinal==2?F04_DEPUTY:0;
 return 0;
}
inline uint64_t odyssey_qualifications(const F04SectionSpec& s) {
 uint64_t mask=1ULL<<s.qualification;
 if(s.id==24)mask|=1ULL<<F04_Q_ASTROMETRY;
 if(s.id==47)mask|=1ULL<<F04_Q_TACTICAL;
 if(s.id==65 || s.id==68)mask|=1ULL<<F04_Q_CLINICAL;
 return mask;
}
